  LargeObject(const LargeObject& other) { std::cout << "LargeObject copy constructor\n"; }

  LargeObject(LargeObject&& other) { std::cout << "LargeObject move constructor\n"; }

  ~LargeObject() { std::cout << "LargeObject destructor\n"; }

};

LargeObject returnLargeObject() {

  LargeObject obj;

  return obj; // RVO candidate

